code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    directions = ((1, 1), (1, -1))

    def orthogonally_isolated(r, c):
        return all(
            not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] == background
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
        )

    for dr, dc in directions:
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == background:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue
                for endpoint, sr, sc in ((run[0], -dr, -dc), (run[-1], dr, dc)):
                    er, ec = endpoint
                    if not orthogonally_isolated(er, ec):
                        continue
                    rr, cc = er + sr, ec + sc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out
'''
